def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = sorted(lst)
    result = []

    while sorted_lst:
        result.append(sorted_lst.pop(0))  # Add the minimum
        if sorted_lst:
            result.append(sorted_lst.pop(-1))  # Add the maximum

    return result

